// Embeds Leaflet + MarkerCluster (installed as devDependencies) into
// src/utils/leafletBundle.ts so the map WebView works offline and no longer
// depends on the unpkg CDN.
//
// Usage: node scripts/gen-leaflet-bundle.mjs   (after bumping leaflet versions)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const nm = (p) => path.join(ROOT, 'node_modules', p);
const read = (p) => fs.readFileSync(nm(p), 'utf8')
  .replace(/\/\/# sourceMappingURL=.*$/gm, '')
  .replace(/\/\*# sourceMappingURL=.*?\*\//g, '')
  // An inline <script> ends at the first "</script", whatever the JS context.
  .replace(/<\/script/gi, '<\\/script');

const parts = {
  LEAFLET_CSS: read('leaflet/dist/leaflet.css'),
  MARKERCLUSTER_CSS: read('leaflet.markercluster/dist/MarkerCluster.css') + '\n'
    + read('leaflet.markercluster/dist/MarkerCluster.Default.css'),
  LEAFLET_JS: read('leaflet/dist/leaflet.js'),
  MARKERCLUSTER_JS: read('leaflet.markercluster/dist/leaflet.markercluster.js'),
};
const version = (p) => JSON.parse(fs.readFileSync(nm(`${p}/package.json`), 'utf8')).version;

let out = `// AUTO-GENERATED by scripts/gen-leaflet-bundle.mjs, do not edit by hand.\n`
  + `// leaflet ${version('leaflet')}, leaflet.markercluster ${version('leaflet.markercluster')}\n\n`;
for (const [k, v] of Object.entries(parts)) out += `export const ${k} = ${JSON.stringify(v)};\n\n`;
const dest = path.join(ROOT, 'src', 'utils', 'leafletBundle.ts');
fs.writeFileSync(dest, out);
console.log(`${path.relative(ROOT, dest)}: ${(out.length / 1024).toFixed(0)} KB`);
